#include <cstdint>
#include <functional>
#include <string>
#include <string_view>
#include <vector>

struct Point
{
    int x, y;
    bool operator==(const Point&) const = default;
};

std::uint64_t fnv1a(std::string_view text)
{
    std::uint64_t h = 14695981039346656037ULL;
    for (unsigned char c : text)
    {
        h ^= c;
        h *= 1099511628211ULL;
    }
    return h;
}

std::uint64_t polyHash(std::string_view text, std::uint64_t base, std::uint64_t mod)
{
    std::uint64_t h = 0;
    for (unsigned char c : text) h = (h * base + c) % mod;
    return h;
}

std::vector<std::uint64_t> windowHashes(std::string_view text, std::size_t k, std::uint64_t base, std::uint64_t mod)
{
    std::vector<std::uint64_t> out;
    if (k == 0 || k > text.size()) return out;
    std::uint64_t top = 1;                                   // base^(k-1) % mod
    for (std::size_t i = 1; i < k; ++i) top = top * base % mod;
    std::uint64_t h = polyHash(text.substr(0, k), base, mod);
    out.push_back(h);
    for (std::size_t i = k; i < text.size(); ++i)
    {
        std::uint64_t leaving = static_cast<unsigned char>(text[i - k]) * top % mod;
        h = (h + mod - leaving) % mod;
        h = (h * base + static_cast<unsigned char>(text[i])) % mod;
        out.push_back(h);
    }
    return out;
}

std::size_t hashCombine(std::size_t seed, std::size_t value)
{
    return seed ^ (value + 0x9e3779b97f4a7c15ULL + (seed << 6) + (seed >> 2));
}

struct PointHash
{
    std::size_t operator()(const Point& p) const
    {
        return hashCombine(std::hash<int>{}(p.x), std::hash<int>{}(p.y));
    }
};

std::vector<std::size_t> bucketSizes(const std::vector<std::string>& keys, std::size_t buckets, std::uint64_t (*hash)(std::string_view))
{
    std::vector<std::size_t> sizes(buckets, 0);
    for (const auto& k : keys) ++sizes[hash(k) % buckets];
    return sizes;
}

