#include <algorithm>
#include <unordered_set>

static std::uint64_t sumHash(std::string_view s) { std::uint64_t h = 0; for (unsigned char c : s) h += c; return h; }

TEST("FNV-1a") {
    CHECK_EQ(fnv1a(""), 14695981039346656037ULL);
    CHECK_EQ(fnv1a("a"), 12638187200555641996ULL);
    CHECK_EQ(fnv1a("stop"), 12618894948741332165ULL);
    CHECK(fnv1a("stop") != fnv1a("pots"));
    CHECK_EQ(fnv1a("\xff"), (14695981039346656037ULL ^ 0xffULL) * 1099511628211ULL);
}
TEST("polynomial hash") {
    CHECK_EQ(polyHash("", 31, 1000000007), 0ULL);
    CHECK_EQ(polyHash("abc", 31, 1000000007), 96354ULL);          // 97*961 + 98*31 + 99
    CHECK_EQ(polyHash("hello", 256, 101), 97ULL);
    CHECK(polyHash("ab", 31, 1000000007) != polyHash("ba", 31, 1000000007));
}
TEST("sliding windows") {
    std::string text = "the quick brown fox jumps over the lazy dog";
    auto hs = windowHashes(text, 3, 131, 1000000007);
    CHECK_EQ(hs.size(), text.size() - 2);
    bool same = true;
    for (std::size_t i = 0; i < hs.size(); ++i) same = same && hs[i] == polyHash(std::string_view(text).substr(i, 3), 131, 1000000007);
    CHECK(same);
    CHECK_EQ(hs[0], hs[31]);                                     // "the" twice
    CHECK(windowHashes("abc", 4, 31, 97).empty());
    CHECK(windowHashes("abc", 0, 31, 97).empty());
    CHECK_EQ(windowHashes("abc", 3, 31, 97).size(), std::size_t{ 1 });
}
TEST("sliding windows over 200,000 characters, window 20,000") {
    std::string big(200000, 'a');
    for (std::size_t i = 0; i < big.size(); ++i) big[i] = static_cast<char>('a' + (i * i + 7 * i) % 26);
    auto hs = windowHashes(big, 20000, 257, 2147483647);
    CHECK_EQ(hs.size(), std::size_t{ 180001 });
    CHECK_EQ(hs[123456], polyHash(std::string_view(big).substr(123456, 20000), 257, 2147483647));
    CHECK_EQ(hs.back(), polyHash(std::string_view(big).substr(180000), 257, 2147483647));
}
TEST("combining and hashing points") {
    CHECK_EQ(hashCombine(0, 0), std::size_t{ 0x9e3779b97f4a7c15ULL });
    PointHash h;
    CHECK(h({ 1, 2 }) != h({ 2, 1 }));
    CHECK(h({ 5, 5 }) != h({ 6, 6 }));
    CHECK_EQ(h({ 3, 4 }), h({ 3, 4 }));
    std::unordered_set<Point, PointHash> seen;
    for (int x = 0; x < 100; ++x) for (int y = 0; y < 100; ++y) seen.insert({ x, y });
    CHECK_EQ(seen.size(), std::size_t{ 10000 });
}
TEST("bucket sizes") {
    std::vector<std::string> keys;
    for (int i = 0; i < 1000; ++i) keys.push_back("key" + std::to_string(i));
    auto good = bucketSizes(keys, 101, fnv1a);
    auto bad = bucketSizes(keys, 101, sumHash);
    CHECK_EQ(good.size(), std::size_t{ 101 });
    std::size_t total = 0;
    for (auto n : good) total += n;
    CHECK_EQ(total, std::size_t{ 1000 });
    CHECK(*std::max_element(good.begin(), good.end()) < 25);
    CHECK(*std::max_element(bad.begin(), bad.end()) > 40);
}

